"""Original Respiratory chapter one: asthma diagnosis and ongoing management."""
from qbank_authoring import question,ref,finalize
GI=ref('GINA Global Strategy for Asthma Management and Prevention, 2026','https://ginasthma.org/wp-content/uploads/2026/05/GINA-2026-Strategy-Report-WMS.pdf')
EX=ref('GINA 2026: Executive Summary and Key Changes','https://doi.org/10.1093/ajrccm/aamag542')
NI=ref('BTS/NICE/SIGN: Asthma Diagnosis, Monitoring and Chronic Management','https://www.nice.org.uk/guidance/ng245/chapter/recommendations')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('Which combination most strongly supports an asthma diagnosis?', 'Variable respiratory symptoms together with objective evidence of variable expiratory airflow',[
 ('Wheeze on one occasion alone','Wheeze has several causes and is not sufficient by itself.'),('A normal chest radiograph alone','It does not establish airway variability.'),('An elevated total IgE without a compatible respiratory pattern','Atopy alone does not diagnose asthma.')],
 'Combine the clinical pattern with measured physiology', '**Symptoms can vary with time, triggers and night or early morning.**',['Spirometry, serial peak flow or selected challenge tests can document variability.','A normal examination between episodes is possible.'], '**Confirm before long-term treatment when feasible without delaying urgent care.**',['ICS can make later confirmation harder by reducing variability.','Revisit alternative diagnoses when the pattern is atypical.'],[['Symptoms','Variable wheeze, breathlessness, cough or tightness'],['Physiology','Variable expiratory airflow'],['Diagnosis','Integrated evidence']],[GI,NI])
q('An adult’s FEV1 rises from 2.0 L to 2.32 L after bronchodilator. Which interpretation is appropriate under the conventional GINA diagnostic criterion?', 'The 320-mL and 16% rise supports variable airflow obstruction',[
 ('The result is negative because the rise is below 500 mL','The conventional adult criterion uses at least 200 mL and 12% from baseline.'),('It proves asthma is the only possible disease','Bronchodilator responsiveness is supportive but not uniquely specific.'),('The percentage change is 3.2%','The change is 0.32/2.0, or 16%.')],
 'Specify the criterion rather than mixing guideline definitions', '**GINA retains the conventional adult diagnostic bronchodilator response framework.**',['ERS/ATS reporting frameworks can use a different predicted-value expression.','The test must still be interpreted with symptoms and quality.'], '**Do not equate a positive response with an exclusive disease label.**',['COPD and mixed phenotypes can also respond.','Document the actual volume and percentage change.'],[['Absolute rise','320 mL'],['Baseline-relative rise','16%'],['Meaning','Supports variability']],[GI],'clinical_scenario')
q('A patient has typical episodic symptoms but normal spirometry while well. What is the best next diagnostic principle?', 'Repeat testing during symptoms or use another validated method to demonstrate variability',[
 ('One normal spirometry permanently excludes asthma','Airflow can be normal between episodes.'),('Diagnose severe asthma without further assessment','The diagnosis and severity are not established.'),('A CT scan alone can replace functional confirmation','It does not demonstrate variable obstruction.')],
 'Sampling time affects sensitivity', '**Serial peak-flow variability or bronchial challenge can help selected cases.**',['Medication use before testing affects responsiveness.','Technical quality must be adequate.'], '**Use a safe tailored confirmation plan.**',['Do not withhold necessary treatment in an unwell patient.','Consider alternate causes if repeated appropriate tests remain unrevealing.'],[['Normal interval test','Does not exclude variability'],['Options','Repeat, PEF or challenge'],['Safety','Treat urgent illness first']],[GI,NI],'clinical_scenario')
q('How should a high FeNO be interpreted in a patient with compatible respiratory symptoms?', 'It supports Type 2 airway inflammation but is not by itself an exclusive asthma diagnosis',[
 ('It proves asthma regardless of all other findings','Atopy and other factors can raise FeNO.'),('A low value excludes all asthma','Non-Type 2 disease and treatment effects can produce low values.'),('It directly measures airway caliber','It is an inflammatory biomarker rather than spirometry.')],
 'Inflammation and airflow physiology are complementary', '**FeNO can help identify corticosteroid-responsive inflammation.**',['Smoking and ICS treatment can lower results.','Interpretation differs among diagnostic algorithms and clinical settings.'], '**Use with symptoms and objective functional evidence.**',['Do not escalate to a biologic solely from one biomarker.','Review adherence and timing when the result is unexpected.'],[['FeNO','Inflammatory information'],['Spirometry','Airflow information'],['Decision','Integrated clinical context']],[GI,NI])
q('What does bronchial provocation testing primarily assess when baseline spirometry is nondiagnostic?', 'Airway hyperresponsiveness',[
 ('The exact cause of every cough','A positive challenge is not fully specific for one disease.'),('Only fixed interstitial fibrosis','It assesses airway response.'),('The presence of a bacterial infection','It is not an infection test.')],
 'A challenge can uncover a latent airway response', '**Methacholine or indirect challenge methods have different properties.**',['Treatment and test preparation affect sensitivity.','Contraindications and baseline lung function determine safety.'], '**Use a protocol with a defined diagnostic question.**',['A negative appropriate test can argue against current asthma.','Interpret a positive result with the symptom pattern.'],[['Target','Hyperresponsiveness'],['Use','Selected nondiagnostic cases'],['Limitation','Not uniquely specific']],[GI,NI])
q('Abrupt exercise-associated throat tightness and inspiratory noise resolve quickly, while asthma treatment has little effect. What alternative should be considered?', 'Inducible laryngeal obstruction',[
 ('Every noisy breath is lower-airway bronchospasm','Inspiratory upper-airway noise suggests another site.'),('Escalate oral steroids indefinitely without confirming the diagnosis','This risks harm without treating the mechanism.'),('A normal resting examination excludes a dynamic laryngeal problem','The obstruction can be episodic.')],
 'Localize the sound and reproduce the relevant physiology', '**ILO can coexist with asthma.**',['Laryngoscopy during symptoms or an appropriate provocation can confirm it.','Exercise-related timing and rapid recovery are useful clues.'], '**Avoid mislabeling all persistent symptoms as severe asthma.**',['Use breathing/speech therapy and specialist care when appropriate.','Retain evidence-based asthma treatment if both conditions are present.'],[['Sound','Often inspiratory/upper airway'],['Course','Episodic and rapidly reversible'],['Confirmation','Laryngeal assessment during symptoms']],[GI],'clinical_scenario')
q('Symptoms improve on holidays and recur during work in a sensitizing environment. What is the best diagnostic approach to possible occupational asthma?', 'Document work-related variability and arrange early specialist assessment while considering safe exposure reduction',[
 ('One normal weekend spirometry excludes a workplace cause','Testing can miss exposure-related variability.'),('Ignore occupational history if allergy tests are negative','Not all occupational asthma is identified by a simple allergy test.'),('Make irreversible employment decisions from one peak-flow reading','A structured assessment is needed.')],
 'The timing pattern can identify an important modifiable cause', '**Serial peak flow at and away from work can help.**',['Specific sensitizers and irritant mechanisms require different evaluation.','Earlier recognition can improve long-term outcome.'], '**Balance health protection and diagnostic planning.**',['Do not continue dangerous exposure simply to obtain a test.','Address employment and compensation implications sensitively.'],[['Clue','Work-versus-away pattern'],['Evidence','Structured serial physiology'],['Care','Early occupational specialist input']],[GI],'clinical_scenario')
q('Why is SABA-only treatment no longer recommended as the ongoing regimen for adults and adolescents with asthma?', 'It does not treat airway inflammation and is associated with greater exacerbation risk than ICS-containing strategies',[
 ('SABA has no bronchodilator effect','It relieves bronchospasm but does not replace anti-inflammatory treatment.'),('Only people with daily symptoms can have severe attacks','Infrequent symptoms do not eliminate attack risk.'),('ICS is needed only after an ICU admission','Anti-inflammatory treatment begins earlier.')],
 'Symptom relief alone can leave the disease process untreated', '**GINA recommends an ICS-containing strategy.**',['Reliever overuse is a risk marker.','The preferred adult/adolescent Track 1 uses ICS-formoterol when appropriate and available.'], '**Provide a practical prescribed regimen and action plan.**',['Do not simply remove the reliever without replacing the plan.','Check technique and access.'],[['SABA','Bronchodilation'],['ICS','Anti-inflammatory protection'],['Goal','Symptoms and exacerbation prevention']],[GI,EX])
q('For an adult with mild asthma suitable for GINA Track 1, what is the preferred reliever strategy?', 'As-needed low-dose ICS-formoterol',[
 ('Salmeterol alone as an acute reliever','It is not the appropriate rapid anti-inflammatory reliever.'),('SABA alone as the entire long-term strategy','This lacks anti-inflammatory protection.'),('Oral prednisolone with every isolated cough','Systemic steroid exposure should not be routine symptom treatment.')],
 'Deliver anti-inflammatory therapy when symptoms prompt inhaler use', '**The strategy reduces severe exacerbations compared with SABA-based care in the studied populations.**',['Product, dose and local licensing matter.','An alternative ICS-containing track is used when Track 1 is unsuitable.'], '**Teach the actual inhaler-specific plan.**',['Daily maintenance may be needed at higher steps.','Do not assume every ICS-LABA combination is interchangeable as a reliever.'],[['Reliever','Low-dose ICS-formoterol'],['Benefit','Anti-inflammatory and rapid bronchodilator'],['Caution','Specific product/regimen']],[GI,EX,NI])
q('What does MART mean in asthma treatment?', 'The prescribed ICS-formoterol inhaler is used for both maintenance and symptom relief',[
 ('Any LABA inhaler can be used without ICS for all roles','MART requires the appropriate ICS-formoterol combination.'),('Maintenance ICS is stopped whenever symptoms occur','The regimen includes both roles.'),('It means repeated oral steroids replace inhaled treatment','That is not MART.')],
 'One compatible combination serves two treatment functions', '**Formoterol has a rapid onset suitable for this reliever role.**',['Maintenance and maximum total daily dosing are formulation specific.','Excess use signals a need for medical assessment.'], '**Use a written action plan.**',['Avoid duplicating incompatible LABA regimens.','Confirm that the patient knows both scheduled and as-needed instructions.'],[['Maintenance','Scheduled ICS-formoterol'],['Relief','Additional prescribed inhalations'],['Safety','Product-specific limits and escalation']],[GI,NI])
q('A patient uses maintenance fluticasone-salmeterol. Can that inhaler automatically be substituted for an ICS-formoterol reliever regimen?', 'No; reliever evidence and dosing are specific to suitable rapid-onset combinations',[
 ('Every ICS-LABA product is equivalent for acute relief','The LABA and formulation matter.'),('Salmeterol alone is safer than the combination for relief','LABA monotherapy is unsafe in asthma.'),('The patient should stop all controller treatment while deciding','A safe replacement plan is required.')],
 'Do not generalize a class label into an interchangeable device instruction', '**MART/AIR evidence does not apply to every combination.**',['Salmeterol is not used in the same rapid-relief role.','A track change requires clear prescribed doses and inhalers.'], '**Reconcile the regimen before switching.**',['Avoid simultaneous incompatible long-acting bronchodilator use.','Teach the new plan and reassess control.'],[['ICS-formoterol','Suitable AIR/MART products'],['ICS-salmeterol','Maintenance role'],['Switching','Needs explicit safe plan']],[GI,NI],'clinical_scenario')
q('Asthma remains uncontrolled on prescribed medium-dose therapy. What should be checked before stepping up?', 'Diagnosis, inhaler technique, adherence, exposures and relevant comorbidities',[
 ('Assume the prescription proves every dose reaches the lungs','Technique and use often limit delivery.'),('Escalate immediately to chronic oral steroids in every case','Modifiable causes should be addressed first.'),('Ignore rhinitis, smoking and obesity','These can affect symptoms and outcomes.')],
 'An apparent pharmacological failure can be a delivery or diagnostic problem', '**Check the inhaler by demonstration rather than asking only if it is used correctly.**',['Access barriers and beliefs affect adherence.','Persistent symptoms can arise from another condition.'], '**Correct treatable factors and reassess.**',['Escalate when true uncontrolled disease remains.','Record exacerbation risk as well as symptom frequency.'],[['Diagnosis','Confirm'],['Delivery','Technique and adherence'],['Context','Triggers and comorbidities']],[GI,EX])
q('Asthma has been well controlled for several months. What is the appropriate step-down principle?', 'Reduce ICS-containing therapy cautiously after assessing risk and with a follow-up plan',[
 ('Stop all ICS permanently as soon as one symptom-free week occurs','This can increase exacerbation risk.'),('Step down during an unstable infection without review','Choose an appropriate stable period.'),('Prior severe exacerbations no longer matter once current symptoms improve','They remain risk factors.')],
 'Find the minimum effective regimen while preserving protection', '**GINA commonly considers step-down after about two to three months of good control.**',['Current lung function and prior attacks affect suitability.','Do not completely stop ICS routinely in adults/adolescents with confirmed asthma.'], '**Document baseline status and an action plan.**',['Make gradual changes and review response.','Use pregnancy and other special contexts carefully.'],[['When','Sustained stable control'],['How','Gradual risk-assessed reduction'],['Safety','ICS protection and follow-up']],[GI,NI])
q('Oropharyngeal candidiasis develops during ICS treatment. Which practical measure can reduce local exposure while preserving necessary asthma treatment?', 'Check technique, use a spacer with a compatible pMDI and rinse the mouth after dosing',[
 ('Stop every anti-inflammatory inhaler permanently','The regimen should be optimized rather than abandoned automatically.'),('A spacer is compatible with every dry-powder device','Spacers are used with suitable pressurized metered-dose devices.'),('Increase the dose solely to treat the thrush','This can worsen the local effect.')],
 'Delivery technique changes local deposition', '**Spacer use and mouth rinsing can reduce local adverse effects with suitable devices.**',['Treat confirmed candidiasis appropriately.','Review whether the dose is the lowest effective amount.'], '**Preserve disease control during adjustments.**',['Device suitability depends on the person’s ability and inspiratory flow.','Demonstration and return-demonstration are useful.'],[['Local problem','Oropharyngeal deposition'],['Measures','Technique, compatible spacer and rinse'],['Goal','Control with fewer adverse effects']],[GI,NI],'clinical_scenario')
q('Why is indefinite ICS dose escalation not always the best response to persistent asthma symptoms?', 'Incremental benefit can diminish while systemic adverse effects increase, and another cause may be present',[
 ('ICS has no dose-response relationship in any patient','Dose matters, but the benefit-risk is not unlimited.'),('High-dose therapy is harmless because it is inhaled','Systemic effects can occur.'),('Biomarkers and technique are irrelevant once any ICS is prescribed','They remain useful in assessment.')],
 'More prescribed drug is not always more effective delivered care', '**High doses can increase adrenal, bone, ocular and other risks.**',['The appropriate step-up can involve combination or phenotype-directed treatment.','Unnecessary exposure should be avoided.'], '**Confirm true uncontrolled disease first.**',['Review adherence, device and alternative diagnoses.','Use specialist evaluation when high-dose treatment is being considered.'],[['Benefit','Can plateau'],['Harm','Rises with exposure'],['Strategy','Correct factors and select appropriate add-on']],[GI])
q('Which principle is essential when prescribing a LABA for asthma?', 'It must be used with an ICS-containing strategy rather than as LABA monotherapy',[
 ('LABA alone treats the underlying inflammation adequately','It does not replace ICS.'),('A normal current peak flow makes LABA monotherapy safe','Current function does not remove the risk.'),('The rule means all combination treatment is prohibited','Appropriate ICS-LABA combinations are central therapies.')],
 'Long-acting bronchodilation must not substitute for inflammatory control', '**LABA monotherapy is associated with serious asthma safety concerns.**',['The combination and regimen must be suitable for the patient.','This asthma rule is not identical to the COPD bronchodilator framework.'], '**Reconcile all inhalers.**',['Avoid accidentally leaving a separate LABA after ICS discontinuation.','Ensure supply and understanding of the full regimen.'],[['LABA','Bronchodilator'],['ICS','Inflammatory protection'],['Asthma','Avoid LABA alone']],[GI])
q('A smoker with asthma has poor control despite treatment. What is an appropriate interpretation?', 'Smoking can worsen outcomes and reduce corticosteroid responsiveness, while requiring cessation support and diagnostic review',[
 ('Smoking proves asthma is impossible','Asthma and smoking can coexist.'),('Steroid resistance means technique and adherence never need checking','They remain important.'),('Cessation is irrelevant once inhalers are prescribed','It remains a major modifiable intervention.')],
 'An exposure can affect both disease and treatment response', '**Smoking increases respiratory risk and can contribute to persistent obstruction.**',['COPD or mixed features need assessment in the appropriate context.','Do not remove indicated ICS solely because the patient smokes.'], '**Provide evidence-based cessation support.**',['Review occupational and household exposures as well.','Optimize a confirmed disease regimen and follow response.'],[['Exposure','Smoking'],['Effect','Worse control and altered response'],['Care','Cessation plus integrated reassessment']],[GI],'clinical_scenario')
q('Asthma, recurrent nasal polyps and respiratory reactions to aspirin or other COX-1 inhibitors occur together. What phenotype is suggested?', 'NSAID-exacerbated respiratory disease',[
 ('An isolated IgE-mediated penicillin allergy','This is a different drug class and mechanism.'),('Every reaction requires a positive aspirin-specific IgE test','The typical COX-1-related mechanism is not established that way.'),('All NSAIDs are automatically safe if used with food','Food does not remove the respiratory risk.')],
 'Upper and lower airway disease can share an eicosanoid-related phenotype', '**COX-1 inhibition can provoke bronchospasm in susceptible patients.**',['Not every person with asthma has this sensitivity.','The choice of analgesic and any challenge requires appropriate expertise.'], '**Manage both asthma and chronic rhinosinusitis.**',['Selected patients benefit from leukotriene modifiers, biologics or supervised desensitization.','Do not attempt an unsupervised diagnostic challenge.'],[['Clues','Asthma and polyps'],['Trigger','COX-1 inhibitors'],['Care','Combined airway and drug-safety plan']],[GI],'clinical_scenario')
